SUBPARTS = [{'id': '2019-12-set1-conv-1', 'subpart_code': 'conv-1', 'section_id': '2019-12-set1-sec-a', 'section_title': 'Section A: Long Conversations', 'type': 'conversation', 'title': 'Conversation 1 · 时尚杂志特稿编辑的日常工作、从业经历与坚持不懈', 'topic_zh': '时尚杂志特稿编辑的日常工作、从业经历与坚持不懈', 'question_range': 'Q1 ~ Q4', 'questions': [1, 2, 3, 4], 'sp_start': 37.0, 'sp_end': 252.0, 'sentences': [('M', 'Today our guest is Rosie Mullender, who works as Features Editor for a fashion magazine.', '今天我们的嘉宾是罗茜·穆伦德，她在一家时尚杂志担任特稿编辑。'), ('M', "Hi Rosie, you're a Features Editor at one of the most widely read women's magazines in the UK.", '你好罗茜，你是英国读者最多的一家女性杂志的特稿编辑。'), ('M', 'What kind of responsibilities does that job entail?', '这项工作包含哪些具体职责？'), ('W', 'We spend our days looking at ideas from journalists, writing copy for the magazine and website, and editing.', '我们平时要审阅记者的各种策划构思，为杂志和网站撰写文稿，并进行编辑审校。'), ('W', 'We also do random things like asking people in the street questions and testing sports clothing.', '我们还会做一些随机的任务，比如在街头采访路人，或者测试运动服装。'), ('W', 'We also do less tangible things like understanding what our readers want.', '我们还会做一些相对无形的工作，比如深入了解我们读者的真实需求。'), ('W', "It's certainly varied and sometimes bizarre.", '这项工作确实非常丰富多样，有时甚至充满奇思妙想。'), ('M', 'During your working day, what kind of work might you typically do?', '在你的工作日里，你通常会做些什么样的工作？'), ('W', 'My day mainly incorporates responding to emails, writing and editing stories, and coming up with new feature ideas.', '我的一天主要包括回复电子邮件、撰写和编辑故事文章，以及构思全新的特稿专题。'), ('M', 'How does the job of Features Editor differ from that of Fashion Editor, or other editorial positions?', '特稿编辑的工作与时尚编辑或其他编辑职位有什么不同？'), ('W', 'The features team deals with articles such as careers, reports, confidence and confessions, everything except fashion and beauty.', '特稿团队负责处理职业发展、调查报告、心理自信以及情感告白等各类文章，涵盖除时尚和美妆之外的所有内容。'), ('M', 'A lot of people believe that working at a magazine is a glamorous job.', '很多人认为在杂志社工作是一份光鲜亮丽的职业。'), ('M', 'Is this an accurate representation of what you do?', '这是对你工作真实情况的准确写照吗？'), ('W', "I'd say it's glamorous to an extent, but not in the way it's portrayed in films.", '我想说在某种程度上它确实很光鲜，但绝不像电影里描绘的那样。'), ('W', 'We do have our moments, such as interviewing celebrities and attending parties, which is a huge thrill.', '我们确实会有风光的时刻，比如采访各路名人和参加派对，这非常令人激动。'), ('W', "Ultimately though, we're the same as our readers, but working in a job we're all very lucky to have.", '不过归根结底，我们和读者并无二致，只是非常幸运能拥有这样一份工作。'), ('M', 'Did you have to overcome any difficulties to reach this point in your career?', '在你的职业生涯中，为了走到今天这一步，你是否必须克服许多困难？'), ('M', 'How did you manage to do this?', '你是如何做到这一点的？'), ('W', 'I had to be really persistent and it was very hard work.', '我必须非常有毅力，而且这是一段极其艰辛的付出。'), ('W', "After three years of working in a petrol station and doing unpaid work, I still hadn't managed to get an entry-level job.", '在加油站工作了三年并做了大量无薪兼职后，我仍然没能获得一份初级职位。'), ('W', 'I was lucky that my last desperate attempt led to a job.', '我很幸运，我最后一次放手一搏的尝试终于让我获得了一份工作。'), ('W', 'I told myself that all experiences make you a better journalist in the long run, and luckily, I was right!', '我告诉自己，从长远来看，所有的经历都会让你成为一名更优秀的记者；幸运的是，我是对的！')]}, {'id': '2019-12-set1-conv-2', 'subpart_code': 'conv-2', 'section_id': '2019-12-set1-sec-a', 'section_title': 'Section A: Long Conversations', 'type': 'conversation', 'title': 'Conversation 2 · 讽刺喜剧《弗兰基》与《生活大爆炸》的观影讨论与创作评价', 'topic_zh': '讽刺喜剧《弗兰基》与《生活大爆炸》的观影讨论与创作评价', 'question_range': 'Q5 ~ Q8', 'questions': [5, 6, 7, 8], 'sp_start': 252.0, 'sp_end': 457.82, 'sentences': [('W', 'Are you watching any good shows these days?', '你最近在看什么好节目吗？'), ('M', 'Actually, yes.', '实际上，是的。'), ('M', "I'm watching a great satire called Frankie.", '我正在看一部很棒的讽刺剧，叫《弗兰基》。'), ('M', "I think you'd like it.", '我觉得你会喜欢的。'), ('W', "Really? What's it about?", '真的吗？它是关于什么的？'), ('M', "It's about a real guy named Frankie.", '它是关于一个叫弗兰基的真实人物。'), ('M', "He's a famous comedian in New York and the show is a mixture of comedy and drama, loosely depicting his life.", '他是纽约的一位著名喜剧演员，该剧融合了喜剧和戏剧元素，大致描绘了他的生活。'), ('W', "I'm sorry, do you mean to say it's a real life series about a real person?", '不好意思，你的意思是说这是一部关于真实人物的真人剧集吗？'), ('W', "It's nonfiction, is it?", '是非虚构类的纪实作品，对吧？'), ('M', 'No, not really, no.', '不，并非如此，不是的。'), ('M', "It's fiction, as what happens in every episode is made up.", '它是虚构剧，因为每一集发生的故事都是虚构出来的。'), ('M', 'However, the lead role is a comedian by the name of Frankie and he plays himself.', '不过，主角是一位名叫弗兰基的喜剧演员，而且他亲自出演自己。'), ('M', 'So Frankie in both real life and in the TV show lives in New York City.', '所以无论是在现实生活中还是在电视剧里，弗兰基都住在纽约市。'), ('M', 'He is a comic, is divorced, and has two little daughters.', '他是一名喜剧演员，离了婚，并带着两个小女儿。'), ('M', 'All those things are true, but aside from him, all his friends and family are played by actors.', '所有这些都是真实的，但除了他本人之外，他所有的亲朋好友都由演员扮演。'), ('M', 'And the plots and events that take place are also invented.', '剧中发生的情节和事件也全是虚构出来的。'), ('W', 'Oh, I think I see now.', '哦，我想我现在明白了。'), ('W', 'That sounds like a very original concept.', '那听起来是一个非常新颖独特的创意。'), ('M', 'Yes, it is.', '是的，确实如此。'), ('M', 'In fact, the whole show is written, directed, edited and produced by him.', '事实上，整部剧集都是由他本人亲自编剧、导演、剪辑和出品的。'), ('M', "And it's very funny and has won many awards.", '而且它非常诙谐幽默，并荣获了多项大奖。'), ('W', "That's cool. I will try to download it.", '太酷了，我会试着下载看看。'), ('W', "I'm watching a comedy called The Big Bang Theory.", '我正在看一部叫做《生活大爆炸》的喜剧。'), ('W', "It's a huge hit around the world.", '它在全世界都非常火爆流行。'), ('M', "Oh, yes. I've heard of it, but never actually watched it.", '哦，是的。我听说过这部剧，但从没真正看过。'), ('W', 'Well, then you should check it out.', '嗯，那你真应该好好看看它。'), ('W', "It's also very funny.", '它也非常搞笑逗乐。'), ('W', "It's about four male scientists and a female waitress.", '它是关于四位男科学家和一名女服务员的故事。'), ('W', 'The men are very socially awkward, but very bright.', '那些男士在社交上非常笨拙拙劣，但智商极高。'), ('W', "And this is contrasted by the lady's social skills and common sense.", '而那位女士出色的社交技能与生活常识恰好与他们形成了鲜明对比。'), ('W', 'The show has been running for over ten years, and some of the actors are practically global superstars now that they are such famous celebrities.', '这部剧已经播出了十多年，由于知名度极高，其中一些演员几乎已经成了享誉全球的超级巨星。')]}, {'id': '2019-12-set1-pass-1', 'subpart_code': 'pass-1', 'section_id': '2019-12-set1-sec-b', 'section_title': 'Section B: Passages', 'type': 'passage', 'title': 'Passage 1 · 身体活动的“用进废退”规律与“保持运动”健康原则', 'topic_zh': '身体活动的“用进废退”规律与“保持运动”健康原则', 'question_range': 'Q9 ~ Q11', 'questions': [9, 10, 11], 'sp_start': 487.82, 'sp_end': 650.0, 'sentences': [('Speaker', 'Related to the "use it or lose it" law is the "keep moving" principle.', '与“用进废退”法则密切相关的是“保持运动”原则。'), ('Speaker', 'We learn about stagnation from nature.', '我们从大自然中汲取关于停滞僵化的教训。'), ('Speaker', 'A river that stops moving gets smelly.', '停止流动的河流会发臭变质。'), ('Speaker', 'The same thing happens to people who stop moving, either mentally or physically.', '同样的事情也会发生在那些在脑力或体力上停止运动的人身上。'), ('Speaker', 'Those who play contact sports know that the player who usually gets hurt the most is the one who is standing still.', '从事身体对抗性运动的人都知道，通常受伤最重的往往是站着不动的那名队员。'), ('Speaker', "Of course, you'll need some time to catch your breath every so often, but the essential message is: keep moving, extending, and learning.", '当然，你时常需要一些时间喘口气歇歇，但核心要旨是：持续运动、拓展并保持学习。'), ('Speaker', 'Ships last a lot longer when they go to sea than when they stay in the harbor.', '轮船出海航行要比一直停泊在港湾里寿命更长。'), ('Speaker', 'The same is true for airplanes.', '飞机也是如此。'), ('Speaker', "You don't preserve an airplane by keeping it on the ground.", '你无法通过让飞机一直停在地面上来保养它。'), ('Speaker', 'You preserve it by keeping it in service.', '你是通过让它持续投入运营来保持其性能的。'), ('Speaker', 'We also get to live a long, healthy life by staying in service.', '同样，我们也是通过让自己保持在岗工作与奉献，才能过上健康长寿的生活。'), ('Speaker', "Japanese statistics reveal that the average person doesn't last very long after retirement.", '日本的统计数据显示，普通人在退休后通常活不了很长时间。'), ('Speaker', "The moral here is: don't retire.", '这里的启示是：不要轻易退休。'), ('Speaker', 'If a fellow says, "I\'m 94 years old and I\'ve worked all my life," we need to realize that is how he got to be 94, by staying involved.', '如果有人说“我已经94岁了，而且我工作了一辈子”，我们需要意识到，正是因为始终保持参与和活跃，他才能活到94岁。'), ('Speaker', 'George Bernard Shaw won a Nobel Prize when he was nearly 70.', '萧伯纳在将近70岁高龄时荣获诺贝尔奖。'), ('Speaker', 'Benjamin Franklin produced some of his best writings at the age of 84.', '本杰明·富兰克林在84岁时写出了一些他最杰出的传世著作。'), ('Speaker', 'And Pablo Picasso put brush to canvas right through his 80s.', '而巴勃罗·毕加索甚至在80多岁高龄时依然挥毫作画。'), ('Speaker', "Isn't the issue how old we think we are?", '关键问题不正是取决于我们在心态上觉得自己有多老吗？'), ('Speaker', 'A bonus with the "keep moving" principle is that while we keep moving, we don\'t have a chance to worry.', '保持运动原则的额外好处是，当我们保持运动时，我们根本没有闲工夫去焦虑担忧。'), ('Speaker', 'Hence, we avoid the dreaded paralysis by analysis.', '因此，我们就能避免因过度思虑而陷入可怕的行动瘫痪。')]}, {'id': '2019-12-set1-pass-2', 'subpart_code': 'pass-2', 'section_id': '2019-12-set1-sec-b', 'section_title': 'Section B: Passages', 'type': 'passage', 'title': 'Passage 2 · 白日梦引发居家意外、注意力分散与创造力提升的双刃剑效应', 'topic_zh': '白日梦引发居家意外、注意力分散与创造力提升的双刃剑效应', 'question_range': 'Q12 ~ Q15', 'questions': [12, 13, 14, 15], 'sp_start': 650.0, 'sp_end': 859.99, 'sentences': [('Speaker', 'In 2014, one in 16 Americans visited the hospital emergency room for home injuries.', '2014年，每16个美国人中就有1人因家庭意外伤害前往医院急诊室就诊。'), ('Speaker', 'One of the main causes of these accidents is a wandering mind.', '导致这些意外事故的主要原因之一是心不在焉、走神开小差。'), ('Speaker', 'By one estimate, people daydream through nearly half of their waking hours.', '据估计，人们在清醒的时间里，有将近一半都在做白日梦走神。'), ('Speaker', 'Psychologists have recently focused on the tendency to think about something other than the task one is doing.', '心理学家们最近将研究重点放在了人们容易去想与手头任务无关之事的这一思绪游离倾向上。'), ('Speaker', 'For one experiment, researchers developed an app to analyze the relationship between daydreaming and happiness.', '在一项实验中，研究人员开发了一款应用程序，用来分析走神与幸福感之间的关联。'), ('Speaker', "They found that the average person's mind wandered most frequently, about 65% of the time, during personal activities such as brushing their teeth and combing their hair.", '他们发现，普通人在刷牙、梳头等个人日常琐事中走神最为频繁，约占65%的时间。'), ('Speaker', "Respondents' minds tended to wander more when they felt upset rather than happy.", '与心情愉悦时相比，受访者在感到沮丧心烦时更容易走神。'), ('Speaker', 'They were more likely to wander toward pleasant topics than unpleasant ones.', '相比不愉快的话题，他们的思绪更有可能游离向令人愉悦的事情。'), ('Speaker', 'How do daydreams affect daydreamers?', '白日梦究竟如何影响做白日梦的人呢？'), ('Speaker', 'A wandering mind leaves us vulnerable when driving.', '在驾驶过程中，心不在焉会让我们陷入危险脆弱的境地。'), ('Speaker', 'In one study, researchers interviewed 955 people involved in traffic accidents.', '在一项研究中，研究人员访谈了955名卷入交通事故的人员。'), ('Speaker', 'The majority of them reported having daydreamed just before the accident.', '其中大多数人都表示在事故发生前一刻正处于走神状态。'), ('Speaker', 'Yet other research suggests that daydreaming has benefits.', '然而，其他研究表明，做白日梦也有一定益处。'), ('Speaker', 'Researchers have found that it gives us a chance to think about our goals.', '研究人员发现，走神为我们提供了审视和思考自身目标的机会。'), ('Speaker', 'And it also seems to increase creativity.', '而且它似乎还能提升人的创造力。'), ('Speaker', 'In one experiment, 145 undergraduates completed four unusual uses tasks, each requiring them to list as many uses as possible for an everyday object.', '在一项实验中，145名本科生完成了四项非常规用途任务，每项任务都要求他们为某日常用品列出尽可能多的用途。'), ('Speaker', 'After the first pair of tasks was completed, one group of participants was assigned an undemanding activity intended to cause their minds to wander.', '在完成前两项任务后，一组参与者被分配了一项轻松简单的活动，旨在促使他们思绪游离走神。'), ('Speaker', 'When all the participants proceeded to the second pair of tasks, the daydreamers performed 40% better than the others.', '当所有参与者继续完成第二组任务时，做白日梦走神的那组人表现比其他人高出40%。')]}, {'id': '2019-12-set1-rec-1', 'subpart_code': 'rec-1', 'section_id': '2019-12-set1-sec-c', 'section_title': 'Section C: Recordings', 'type': 'recording', 'title': 'Recording 1 · 北欧维京木制教堂的历史演变、建筑结构与保护现状', 'topic_zh': '北欧维京木制教堂的历史演变、建筑结构与保护现状', 'question_range': 'Q16 ~ Q18', 'questions': [16, 17, 18], 'sp_start': 899.0, 'sp_end': 1130.0, 'sentences': [('Speaker', 'Dating from as far back as the 12th century, they are claimed to be the rarest historic buildings in Western Europe.', '这些建筑的历史最早可追溯至12世纪，被认为是西欧最为罕见的历史建筑。'), ('Speaker', "These buildings offer vital insights into Scandinavia's Viking past, but now, with only 30 wooden churches remaining and their condition deteriorating, experts are working to preserve the structures for future generations.", '这些建筑为我们深入了解斯堪的纳维亚半岛的维京历史提供了重要见解，但如今仅存30座木制教堂且建筑状况日益恶化，专家们正努力保护这些结构，以便留传给后代。'), ('Speaker', 'Some of these spectacular churches are no more than small buildings, barely four metres wide and six metres tall.', '在这些壮观的教堂中，有些不过是些小巧的建筑，宽度仅约4米，高约6米。'), ('Speaker', 'Others are much larger structures that soar up to 40 metres into the cold air.', '另一些则是规模大得多的宏伟结构，巍然耸立高达40米，直插寒冷的云霄。'), ('Speaker', 'Most consist of timber frames that rest on stone blocks.', '大多数教堂由支承在石块上的木框架构成。'), ('Speaker', 'This means that they have no foundations.', '这意味着它们并没有深埋于地下的传统地基。'), ('Speaker', 'Although many of the churches appear from the outside to be complex structures, they normally feature only a single story, but numerous different roof levels.', '虽然许多教堂从外观看起来结构复杂，但它们通常只有单层高度，却拥有多层错落有致的屋顶。'), ('Speaker', 'Staff from the Norwegian government have carried out conservation work on ten of the churches over the past two years.', '在过去两年里，挪威政府的工作人员已经对其中的10座教堂开展了修缮保护工作。'), ('Speaker', 'Most of these churches date from between the 12th and 14th centuries.', '这些教堂大多建于12世纪至14世纪之间。'), ('Speaker', 'Other churches were conserved in previous years.', '其余部分教堂在早些年间也已完成保护性修缮。'), ('Speaker', "So far, specialists have worked to add preservative materials to the churches' exteriors.", '到目前为止，专家们致力于在教堂外立面添加防腐保护材料。'), ('Speaker', 'They also replaced rotting roofs and halted the sinking of the churches into the ground.', '他们还更换了腐朽的屋顶，并有效遏制了教堂向地面下陷的趋势。'), ('Speaker', 'In two cases, huge machines have been used to lift the buildings up to 30 centimetres into the air.', '在两起案例中，工程团队甚至使用大型机械将整栋建筑在空中整体顶升了多达30厘米。'), ('Speaker', "This was accomplished so that the team could examine and repair the churches' original medieval stone blocks.", '这样做是为了使施工团队能够仔细检查并修复教堂原有的中世纪石基砌块。'), ('Speaker', 'The team plans to return to around a dozen of the buildings to assess progress and consider further action.', '该团队计划回访约十几座建筑，以评估修缮进展并商议进一步的保护措施。'), ('Speaker', 'The earliest free-standing wooden church was probably built in Norway in around 1080.', '最早的独立木制教堂大约于公元1080年在挪威建成。'), ('Speaker', 'However, the largest known wooden churches were built from the 1130s onwards.', '然而，已知规模最大的木制教堂大多是在1130年代以后建造的。'), ('Speaker', 'This period was one of inter-elite rivalry, in which nobles sought to increase their influence by funding the construction of churches and other buildings.', '这一时期是统治精英阶层相互竞争的时代，贵族们试图通过资助修建教堂和其他地标建筑来扩大自身政治影响力。'), ('Speaker', "The reason for constructing the buildings from wood is probably that ideally proportioned, straight and slender timber was available in large quantities in Scandinavia's vast pine forests.", '之所以选择木材建造这些建筑，很可能是因为在斯堪的纳维亚广袤的松树森林中，可以大量获取比例匀称、笔直且修长的优质木材。'), ('Speaker', 'As wood was so plentiful, it was cheaper to use than the stone used in the buildings of other European cultures.', '由于木材资源极其丰富，使用木材建造成本远比欧洲其他文明建筑所使用的石料更加低廉。'), ('Speaker', "The area's shipbuilding tradition, partly established by the Vikings, also meant that sophisticated carpentry was a major aspect of the local culture.", '部分由维京人开创的当地造船传统，也意味着精湛高超的木工技艺是当地传统文化的重要组成部分。')]}, {'id': '2019-12-set1-rec-2', 'subpart_code': 'rec-2', 'section_id': '2019-12-set1-sec-c', 'section_title': 'Section C: Recordings', 'type': 'recording', 'title': 'Recording 2 · 发展心理学研究：人类婴儿对音乐情绪感知与惊人认知能力', 'topic_zh': '发展心理学研究：人类婴儿对音乐情绪感知与惊人认知能力', 'question_range': 'Q19 ~ Q21', 'questions': [19, 20, 21], 'sp_start': 1130.0, 'sp_end': 1385.0, 'sentences': [('Speaker', "In last week's lecture, we discussed the characteristics of the newly born offspring of several mammals.", '在上一周的讲座中，我们讨论了几种哺乳动物新生幼崽的特征。'), ('Speaker', 'You probably remember that human infants are less developed physically than other mammals of the same age.', '大家可能还记得，人类婴儿在身体发育程度上落后于同龄的其他哺乳动物。'), ('Speaker', "But in today's lecture, we'll look at three very interesting studies that hint at the surprising abilities of human babies.", '但在今天的讲座中，我们将着眼于三项非常有趣的研究，它们揭示了人类婴儿令人惊叹的非凡能力。'), ('Speaker', "In the first study, three-year-olds watched two videos shown side by side, each featuring a different researcher, one of whom they'd met once, two years earlier.", '在第一项研究中，三岁大的幼儿并排观看了两段视频，每段视频中各有一名不同的研究人员，其中一人他们在两年前只见过一次。'), ('Speaker', "The children spent longer watching the video showing the researcher they hadn't met.", '孩子们花更长的时间注视着播放他们从未见过的那位研究人员的视频。'), ('Speaker', "This is consistent with young children's usual tendency to look longer at things that aren't familiar.", '这与幼儿通常倾向于对不熟悉的事物注视更长时间的习惯是一致的。'), ('Speaker', 'And really, this is amazing.', '而且说真的，这太令人惊奇了。'), ('Speaker', "It suggests the children remembered the researcher they'd met just one time when they were only one-year-olds.", '这表明孩子们记住了他们在仅仅一岁时只见过一次的研究人员。'), ('Speaker', 'Of course, as most of us forget memories from our first few years as we grow older, these early long-term memories will likely be lost in subsequent years.', '当然，随着年龄的增长，我们大多数人都会遗忘生命最初几年的记忆，这些早期的长期记忆很可能在随后的岁月中逐渐遗忘。'), ('Speaker', 'Our second study is about music.', '我们的第二项研究是关于音乐的。'), ('Speaker', 'For this study, researchers played music to babies through speakers located on either side of a human face.', '在这项研究中，研究人员通过位于一张人脸两侧的扬声器向婴儿播放音乐。'), ('Speaker', 'They waited until the babies got bored and averted their gaze from the face.', '他们一直等到婴儿感到厌倦并将目光从人脸上移开。'), ('Speaker', 'And then they changed the mood of the music, either from sad to happy or the other way around.', '然后他们改变了音乐的情绪基调，要么从悲伤转为欢快，要么反过来。'), ('Speaker', 'This mood switch made no difference to the three-month-olds, but for the nine-month-olds, it was enough to renew their interest and they started looking again in the direction of the face.', '这种情绪转变对三个月大的婴儿毫无影响，但对九个月大的婴儿而言，这足以重新唤起他们的兴趣，他们开始重新将目光投向那张人脸的方向。'), ('Speaker', 'This suggests that babies of that age can tell the difference between a happy melody and a sad tune.', '这表明该年龄段的婴儿已经能够分辨出欢快的旋律与悲伤的曲调之间的区别。'), ('Speaker', "Our final study is from 1980, but it's still relevant today.", '我们的最后一项研究来自1980年，但它至今仍具有重要的现实意义。'), ('Speaker', "In fact, it's one of the most famous pieces of research about infant emotion ever published.", '事实上，它是有史以来发表的关于婴儿情绪的最著名的研究之一。'), ('Speaker', 'The study involved ordinary adults watching video clips of babies nine months or younger.', '这项研究让普通成年人观看九个月或更小婴儿的视频片段。'), ('Speaker', 'In the video clips, the babies made various facial expressions in response to real-life events, including playful interactions and painful ones.', '在视频片段中，婴儿们针对现实生活中的事件做出了各种各样的面部表情，包括嬉戏玩耍和痛苦难受的场景。'), ('Speaker', "The adult observers were able to reliably discern an assortment of emotions on the babies' faces.", '成年观察者能够非常可靠地从婴儿的面部辨认出各种各样的情绪。'), ('Speaker', 'These emotions included interest, joy, surprise, sadness, anger, disgust, contempt, and fear.', '这些情绪包括兴趣、喜悦、惊讶、悲伤、愤怒、厌恶、轻蔑以及恐惧。'), ('Speaker', "Next week, we'll be looking at this last study more closely.", '下周，我们将更深入地剖析这最后一项研究。'), ('Speaker', "In fact, we will be viewing some of the video clips from that study, and together, see how well we do in discerning the babies' emotions.", '事实上，我们将一起观看该研究中的部分视频片段，共同检验我们在识别婴儿情绪方面的表现如何。')]}, {'id': '2019-12-set1-rec-3', 'subpart_code': 'rec-3', 'section_id': '2019-12-set1-sec-c', 'section_title': 'Section C: Recordings', 'type': 'recording', 'title': 'Recording 3 · 团队过度合作的潜在弊端、共识陷阱与高效协作边界', 'topic_zh': '团队过度合作的潜在弊端、共识陷阱与高效协作边界', 'question_range': 'Q22 ~ Q25', 'questions': [22, 23, 24, 25], 'sp_start': 1385.0, 'sp_end': 1687.04, 'sentences': [('Speaker', "Today, I'd like to talk about the dangers of being too collaborative.", '今天，我想谈谈过度合作的潜在危险。'), ('Speaker', 'Being a good team player is an essential skill in our modern workplace.', '在现代职场中，成为一名优秀的团队合作者是一项必不可少的技能。'), ('Speaker', 'The ability to work well with others and collaborate on projects is a sought-after ability in nearly every position.', '与他人融洽共事并在项目中精诚合作的能力，几乎在所有职位中都备受青睐。'), ('Speaker', 'However, placing too much emphasis on being a good team player can negatively affect your career growth.', '然而，过于强调做一名优秀的团队合作者，会对你的职业发展产生负面影响。'), ('Speaker', "Don't be overly focused on gaining consensus.", '不要过分执着于达成所有人的共识。'), ('Speaker', "Don't be too concerned with the opinions of others.", '不要对别人的意见过于顾虑敏感。'), ('Speaker', 'This can hinder your ability to make decisions, speak up, and gain recognition for your individual skills and strengths.', '这会削弱你果断决策、大胆发声以及让个人的专业技能与优势获得认可的能力。'), ('Speaker', "Some people are too subordinate to others' opinions, too focused on decision consensus, too silent about their own points of view, and too agreeable to take things on when they don't have time or energy.", '有些人对别人的意见过于顺从，过分追求决策共识，在自己的观点上过于沉默，在没有时间和精力时又过分顺从地承担额外工作。'), ('Speaker', 'This leads to building a brand of underconfident, submissive, low-impact non-leaders, and hampers their growth and career advancement.', '这会导致树立起一种缺乏自信、言听计从、缺乏影响力、缺乏领导力的职业人设，从而阻碍他们的成长和职场晋升。'), ('Speaker', 'Collaboration certainly makes your individual competencies and contributions more difficult for outsiders to identify.', '团队合作无疑会让外人更难辨识出你的个人能力与贡献。'), ('Speaker', "Collaborative projects mean you're sharing the spotlight with others.", '合作项目意味着你必须与他人共同分享聚光灯。'), ('Speaker', 'Outsiders may then find it difficult to determine your contributions and strengths.', '因此，外界可能会很难准确判定你的具体贡献和专业特长。'), ('Speaker', 'This may end up costing you opportunities for promotions or pay raises.', '这最终可能会让你失去晋升或加薪的宝贵机会。'), ('Speaker', "You certainly shouldn't ditch teamwork, but how can you avoid the hazards of being an over-collaborator?", '当然，你绝不应该摒弃团队合作，但你该如何避免成为过度合作者的陷阱呢？'), ('Speaker', 'Working in a team can have huge benefits.', '在团队中工作确实可以带来巨大的益处。'), ('Speaker', 'Your team may have repeated successes and often gain recognition.', '你的团队可能会屡创佳绩，并频繁获得各方表彰。'), ('Speaker', "You'll then have more opportunities to expand your professional network than if you worked alone.", '这样一来，你将比单打独斗拥有更多拓宽职业人脉网络的机会。'), ('Speaker', 'However, finding a balance between team efforts and individual projects that give you independent recognition is important for making a name for yourself and providing opportunities for advancement.', '然而，在团队付出与能够为你带来独立认可的个人项目之间找到平衡，对于树立个人声望和争取晋升机会至关重要。'), ('Speaker', 'Be selective in who you work with.', '在选择与谁合作时要有所挑选。'), ('Speaker', 'This will maximize the benefits and minimize the downsides of being a team player.', '这将最大化团队合作的好处，并最大限度减少作为团队成员的弊端。'), ('Speaker', 'Collaborate with people who have complementary expertise.', '与拥有互补专业知识的人开展合作。'), ('Speaker', "Select projects where there's potential for mutual benefit.", '挑选具有互利共赢潜力的合作项目。'), ('Speaker', "Perhaps you're bringing your unique knowledge and gaining access to someone else's professional network.", '也许你奉献了独特的专业知识，同时借此打入了别人的专业人脉圈。'), ('Speaker', "Or maybe you're able to learn a new skill by working with someone.", '或者你能够通过与某人共事掌握一项全新的技能。'), ('Speaker', 'Seek out your teammates purposefully rather than jumping on every new group project opportunity.', '有针对性地主动物色你的队友，而不是盲目扎进每一个新的团队项目机会中。'), ('Speaker', 'When we are too collaborative, we want everyone to agree with a decision before we proceed.', '当我们过度追求合作时，我们总是希望在推进工作之前所有人都对某项决策达成一致。'), ('Speaker', 'This can create unnecessary delays as you hold meetings trying to achieve a consensus.', '随着你一次次召开会议试图达成共识，这会造成不必要的延误。'), ('Speaker', "It's fine to be collaborative when seeking input, but put a deadline on the input stage and arrive at a decision, even if it's a decision that doesn't have consensus.", '在征求意见阶段注重合作是件好事，但务必给意见收集阶段设定一个截止日期，并果断做出决策，即使这是一项并未达成全员共识的决定。')]}]

QUESTIONS = {1: {'prompt': "What is the woman's profession?", 'options': {'A': 'Magazine reporter', 'B': 'Fashion designer', 'C': 'Website designer', 'D': 'Features editor'}, 'answer': 'D', 'explanation': '【精析】细节辨认题。男士在开篇介绍女士身份：“Today our guest is Rosie Mullender, who works as Features Editor for a fashion magazine.”女士在时尚杂志担任特稿编辑（Features Editor）。因此答案为 D)。'}, 2: {'prompt': "What is one of the woman's main responsibilities?", 'options': {'A': 'Designing sports clothing', 'B': 'Consulting fashion experts', 'C': 'Answering daily emails', 'D': 'Interviewing job-seekers'}, 'answer': 'C', 'explanation': '【精析】细节辨认题。女士详细回答其工作日职责：“My day mainly incorporates responding to emails, writing and editing stories, and coming up with new feature ideas.”构思新的专题报道（coming up with new feature ideas / creating new feature topics）是其核心职责之一。因此答案为 C)。'}, 3: {'prompt': "What do many people think about the woman's job?", 'options': {'A': 'It is challenging.', 'B': 'It is fascinating.', 'C': 'It is tiresome.', 'D': 'It is fashionable.'}, 'answer': 'B', 'explanation': "【精析】细节推断题。男士询问大多数人是否认为杂志工作极富魅力：“A lot of people believe that working at a magazine is a glamorous job.”女士也承认：“I'd say it's glamorous to an extent...”即大多数人认为这项工作光鲜迷人（fascinating / glamorous）。因此答案为 B)。"}, 4: {'prompt': 'What helped the woman to get her current position?', 'options': {'A': 'Her persistence', 'B': 'Her experience', 'C': 'Her competence', 'D': 'Her confidence Questions 5 to 8 are based on the conversation you have just heard.'}, 'answer': 'A', 'explanation': '【精析】细节辨认题。当男士询问如何克服职业初期的艰难险阻时，女士回答：“I had to be really persistent and it was very hard work.”强调持之以恒、坚持不懈（Her persistence）是她取得如今职位的关键。因此答案为 A)。'}, 5: {'prompt': 'What does the man think of the satire Frankie he recently watched?', 'options': {'A': 'It is enjoyable.', 'B': 'It is educational.', 'C': 'It is divorced from real life.', 'D': 'It is adapted from a drama.'}, 'answer': 'A', 'explanation': "【精析】观点态度题。男士评价自己正在观看的讽刺喜剧《弗兰基》：“I'm watching a great satire called Frankie... In fact, the whole show is written, directed, edited and produced by him. And it's very funny and has won many awards.”男士认为该剧非常滑稽有趣（It is full of fun）。因此答案为 A)。"}, 6: {'prompt': 'What does the man say is special about the satire Frankie?', 'options': {'A': 'All the roles are played by famous actors and actresses.', 'B': 'It is based on the real-life experiences of some celebrities.', 'C': 'Its plots and events reveal a lot about Frankie’s actual life.', 'D': 'It is written, directed, edited and produced by Frankie himself'}, 'answer': 'D', 'explanation': '【精析】细节辨认题。男士介绍该剧的特别之处：“the whole show is written, directed, edited and produced by him.”整部剧完全由弗兰基自编自导自剪并亲自出品（written, directed, edited and produced by Frankie himself）。因此答案为 D)。'}, 7: {'prompt': 'What does the woman say she is going to do with the satire Frankie?', 'options': {'A': 'Go to the theater and enjoy it.', 'B': 'Recommend it to her friends.', 'C': 'Watch it with the man.', 'D': 'Download and watch it.'}, 'answer': 'D', 'explanation': "【精析】动作意向题。女士听到介绍后表现出极大兴趣：“That sounds like a very original concept... That's cool. I will try to download it.”女士表示打算下载这部剧来观看（Download and watch it）。因此答案为 D)。"}, 8: {'prompt': 'What does the woman say about the comedy The Big Bang Theory?', 'options': {'A': ',', 'B': ',', 'C': 'and', 'D': '. Then mark the corresponding letter on Answer Sheet 1 with a single line through the center. Questions 9 to 11 are based on the passage you have just heard.'}, 'answer': 'B', 'explanation': '【精析】细节辨认题。女士介绍自己喜欢的喜剧《生活大爆炸》：“The show has been running for over ten years, and some of the actors are practically global superstars.”该剧已经连续播出了十余年（It has been on for over ten years）。因此答案为 B)。'}, 9: {'prompt': 'What does the speaker say about players of contact sports?', 'options': {'A': 'They are likely to get injured when moving too fast.', 'B': 'They believe in team spirit for good performance.', 'C': 'They need to keep moving to avoid getting hurt.', 'D': 'They have to learn how to avoid body contact.'}, 'answer': 'C', 'explanation': '【精析】细节辨认题。讲话人借对抗性体育运动阐明“保持运动”原则：“Those who play contact sports know that the player who usually gets hurt the most is the one who is standing still.”站着不动的球员通常受伤最严重（Those who stay motionless get hurt most often）。因此答案为 C)。'}, 10: {'prompt': 'What do longevity statistics reveal about the average person?', 'options': {'A': 'They do not have many years to live after retirement.', 'B': 'They tend to live a longer life with early retirement.', 'C': 'They do not start enjoying life until full retirement.', 'D': 'They keep themselves busy even after retirement.'}, 'answer': 'A', 'explanation': "【精析】细节推断题。讲话人引述日本退休统计数据：“Japanese statistics reveal that the average person doesn't last very long after retirement.”普通人在退休后往往寿命不会延续太久（They do not have many years to live after retirement）。因此答案为 A)。"}, 11: {'prompt': 'What bonus does the keep moving principle bring us according to the speaker?', 'options': {'A': 'It prevents us from worrying.', 'B': 'It slows down our aging process.', 'C': 'It enables us to accomplish more in life.', 'D': 'It provides us with more chances to learn. Questions 12 to 15 are based on the passage you have just heard.'}, 'answer': 'A', 'explanation': "【精析】细节辨认题。讲话人指出保持运动的额外好处：“A bonus with the keep moving principle is that while we keep moving, we don't have a chance to worry. Hence, we avoid the dreaded paralysis by analysis.”在持续行动中，人们没有时间去焦虑担忧（It prevents us from worrying）。因此答案为 A)。"}, 12: {'prompt': "What does the passage say about people's minds?", 'options': {'A': 'It tends to dwell upon their joyous experiences.', 'B': 'It wanders for almost half of their waking time.', 'C': 'It has trouble concentrating after a brain injury.', 'D': 'It tends to be affected by their negative feelings.'}, 'answer': 'B', 'explanation': "【精析】细节事实题。文章开头指出：“By one estimate, people daydream through nearly half of their waking hours.”人们清醒时间里将近一半都在走神做白日梦（People's minds wander nearly half of the time when they are awake）。因此答案为 B)。"}, 13: {'prompt': 'For what purpose did the researchers develop the new app?', 'options': {'A': 'To find how happiness relates to daydreaming.', 'B': 'To observe how one’s mind affects one’s behavior.', 'C': 'To see why daydreaming impacts what one is doing.', 'D': 'To study the relation between health and daydreaming.'}, 'answer': 'A', 'explanation': '【精析】目的意图题。文中明确说明实验目的：“researchers developed an app to analyze the relationship between daydreaming and happiness.”研究人员开发该应用旨在分析走神与幸福感之间的关联（To find out the link between mind wandering and happiness）。因此答案为 A)。'}, 14: {'prompt': 'How does daydreaming benefit people according to some researchers?', 'options': {'A': 'It helps them make good decisions.', 'B': 'It helps them tap their potentials.', 'C': 'It contributes to their creativity.', 'D': 'It contributes to clear thinking'}, 'answer': 'C', 'explanation': '【精析】细节辨认题。研究表明做白日梦走神也有益处：“Researchers have found that it gives us a chance to think about our goals. And it also seems to increase creativity.”它能够激发和提升创造力（It increases creativity）。因此答案为 C)。'}, 15: {'prompt': 'What was the finding of the experiment with 145 undergraduates?', 'options': {'A': ',', 'B': ',', 'C': 'and', 'D': '. Then mark the corresponding letter on Answer Sheet 1 with a single line through the center. Questions 16 to 18 are based on the recording you have just heard.'}, 'answer': 'D', 'explanation': '【精析】实验结果题。文中详述145名本科生对照实验：“When all the participants proceeded to the second pair of tasks, the daydreamers performed 40% better than the others.”做白日梦的那组人任务表现比其他人高出40%（Those whose minds wandered did 40% better than others）。因此答案为 D)。'}, 16: {'prompt': 'What does the speaker say about the Viking wooden churches?', 'options': {'A': 'They are the oldest buildings in Europe.', 'B': 'They are part of the Christian tradition.', 'C': 'They are renovated to attract tourists.', 'D': 'They are in worsening condition.'}, 'answer': 'D', 'explanation': '【精析】细节事实题。文中指出维京木制教堂现状堪忧：“now, with only 30 wooden churches remaining and their condition deteriorating, experts are working to preserve the structures...”如今仅存30座且建筑状况日益恶化（Only a small number of them have survived and they are deteriorating）。因此答案为 D)。'}, 17: {'prompt': 'What is special about most of the Viking wooden churches?', 'options': {'A': 'They have a history of 14 centuries.', 'B': 'They are 40 metres tall on average.', 'C': 'They are without foundations.', 'D': 'They consist of several storeys.'}, 'answer': 'C', 'explanation': '【精析】建筑特征题。文中说明大部分教堂的构造：“most consist of timber frames that rest on stone blocks. This means that they have no foundations.”木框架直接支承在石块上，没有埋入地下的地基（They have no foundations）。因此答案为 C)。'}, 18: {'prompt': 'Why were the Viking churches constructed from wood?', 'options': {'A': 'Wood was harmonious with nature.', 'B': 'Wooden buildings kept the cold out.', 'C': 'Timber was abundant in Scandinavia.', 'D': 'The Vikings liked wooden structures. Questions 19 to 21 are based on the recording you have just heard.'}, 'answer': 'C', 'explanation': "【精析】原因解释题。文中分析选用木材的原因：“ideally proportioned, straight and slender timber was available in large quantities in Scandinavia's vast pine forests.”斯堪的纳维亚广袤的松林提供了大量笔直匀称的木材资源（Scandinavia was rich in suitably proportioned wood）。因此答案为 C)。"}, 19: {'prompt': 'What are the three interesting studies about?', 'options': {'A': 'Similarities between human babies and baby animals.', 'B': 'Cognitive features of different newly born mammals.', 'C': 'Adults influence on children.', 'D': 'Abilities of human babies.'}, 'answer': 'D', 'explanation': "【精析】主旨要义题。讲座开篇点明主题：“in today's lecture we'll look at three very interesting studies that hint at the surprising abilities of human babies.”讲座聚焦于三项揭示人类婴儿惊人能力的研究（They hint at the incredible abilities of human babies）。因此答案为 D)。"}, 20: {'prompt': 'What does the second study find about nine-month-old babies?', 'options': {'A': 'They can distinguish a happy tune from a sad one.', 'B': 'They love happy melodies more than sad ones.', 'C': 'They fall asleep easily while listening to music.', 'D': 'They are already sensitive to beats and rhythms.'}, 'answer': 'A', 'explanation': '【精析】实验结论题。讲座介绍音乐研究结果：“This mood switch made no difference to the three-month-olds, but for the nine-month-olds, it was enough to renew their interest... This suggests that babies of that age can tell the difference between a happy melody and a sad tune.”九个月大的婴儿能够区分欢快与悲伤的旋律（They can distinguish between happy and sad tunes）。因此答案为 A)。'}, 21: {'prompt': 'What is the 1980 study about?', 'options': {'A': 'Infants’ facial expressions.', 'B': 'Babies’ emotions.', 'C': 'Babies’ interaction with adult.', 'D': 'Infants’ behaviors. Questions 22 to 25 are based on the recording you have just heard.'}, 'answer': 'B', 'explanation': "【精析】事实辨认题。讲话人介绍1980年的经典研究：“it's one of the most famous pieces of research about infant emotion ever published.”该研究是关于婴儿情绪识别的里程碑式研究（Infants' emotional expressions）。因此答案为 B)。"}, 22: {'prompt': 'What does the speaker say about being over-collaborative?', 'options': {'A': 'It may harm the culture of today’s workplace.', 'B': 'It may hinder individual career advancement.', 'C': 'It may result in unwillingness to take risks.', 'D': 'It may put too much pressure on team members.'}, 'answer': 'B', 'explanation': "【精析】主旨观点题。讲话人开篇直陈过度合作的危害：“placing too much emphasis on being a good team player can negatively affect your career growth... hampers their growth and career advancement.”过分强调团队合作会阻碍个人的职业成长与晋升（It may hinder a person's career growth）。因此答案为 B)。"}, 23: {'prompt': 'What does the speaker say about people engaged in collaborative projects?', 'options': {'A': 'They can hardly give expression to their original views.', 'B': 'They can become less motivated to do projects of their own.', 'C': 'They may find it hard to get their contributions recognized.', 'D': 'They may eventually lose their confidence and creativity'}, 'answer': 'C', 'explanation': '【精析】细节辨认题。讲话人分析合作项目对个人的遮蔽效应：“Collaboration certainly makes your individual competencies and contributions more difficult for outsiders to identify... Outsiders may then find it difficult to determine your contributions and strengths.”合作会使外界很难单独辨识和认可个人的贡献与能力（They may find it hard to get their contributions recognized）。因此答案为 C)。'}, 24: {'prompt': 'How do people benefit from working in a team?', 'options': {'A': 'They can enlarge their professional circle.', 'B': 'They can get chances to engage in research.', 'C': 'They can make the best use of their expertise.', 'D': 'They can complete the project more easily.'}, 'answer': 'A', 'explanation': "【精析】细节辨认题。讲话人阐述团队工作的积极意义：“You'll then have more opportunities to expand your professional network than if you worked alone.”参与团队能够让人获得更多机会拓展自己的专业人脉圈（They can enlarge their professional circle）。因此答案为 A)。"}, 25: {'prompt': 'Why is it undesirable to spend too much time trying to reach consensus?', 'options': {'A': 'It may cause lots of arguments in a team.', 'B': 'It may prevent making a timely decision.', 'C': 'It may give rise to a lot of unnecessary expenses.', 'D': 'It may deprive a team of business opportunities.'}, 'answer': 'B', 'explanation': '【精析】原因解释题。讲话人警告盲目追求共识的弊端：“This can create unnecessary delays as you hold meetings trying to achieve a consensus.”过分追求共识会频繁开会而导致决策延误（It may prevent making a timely decision）。因此答案为 B)。'}}
